solution.css:
/* Profile card · style.css */

/* Step 4: the whole page */
body {
  font-family: Arial, sans-serif;
  background-color: #f1e9f6;
  color: #222222;
}

/* Steps 5 and 6: the card box, centred */
.card {
  max-width: 360px;
  margin: 40px auto;
  padding: 24px;
  background-color: #ffffff;
  border: 3px solid #602b7a;
  border-radius: 16px;
  text-align: center;
}

/* Step 7: round photo and button */
.card img {
  width: 120px;
  border: 4px solid #d4de00;
  border-radius: 50%;
}

.role {
  color: #602b7a;
  font-weight: bold;
}

.links {
  list-style: none;
  padding: 0;
}

.links li {
  margin: 8px 0;
}

.links a {
  color: #602b7a;
}

button {
  padding: 10px 20px;
  border: none;
  border-radius: 8px;
  background-color: #602b7a;
  color: #ffffff;
  font-size: 16px;
  cursor: pointer;
}

/* Dark theme (step 9): JavaScript adds the class "dark" to <body> */
body.dark {
  background-color: #1e1527;
}

solution.js:
// Profile card · script.js

// Step 8: select the button and listen to clicks
const themeBtn = document.querySelector("#theme-btn");

themeBtn.addEventListener("click", () => {
  console.log("Theme changed");

  // Step 9: switch the theme and update the button text
  document.body.classList.toggle("dark");

  if (document.body.classList.contains("dark")) {
    themeBtn.textContent = "Light mode";
  } else {
    themeBtn.textContent = "Dark mode";
  }
});
